#!/usr/bin/env python3
"""Map edits of lane c17-repair-owed-record-r16-cell-nodes (owed list of campaign round 16).
Edits push/OBSTRUCTION_MAP.md in place; the previous file is before/OBSTRUCTION_MAP.md next to this script.
Every anchor must match exactly once. No row is a statement about zeros of zeta."""
import os
HERE = os.path.dirname(os.path.abspath(__file__))
P = os.path.normpath(os.path.join(HERE, '..', 'OBSTRUCTION_MAP.md'))
lines = open(P, encoding='utf-8').read().split('\n')
log = []

def line_of(prefix):
    idx = [k for k, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, (prefix, len(idx))
    return idx[0]

def rep(prefix, a, b):
    k = line_of(prefix)
    assert lines[k].count(a) == 1, (prefix, a[:70], lines[k].count(a))
    lines[k] = lines[k].replace(a, b)
    log.append('edited ' + prefix.strip())

def insert_after(prefix, text):
    k = line_of(prefix)
    lines.insert(k + 1, text)
    log.append('inserted after ' + prefix.strip() + ': ' + text[:40])

